CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,sort INT DEFAULT 0) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS items(id INT AUTO_INCREMENT PRIMARY KEY,cat_id INT NOT NULL,name VARCHAR(120) NOT NULL,descr VARCHAR(500) DEFAULT '',price DECIMAL(10,3) NOT NULL,image VARCHAR(500) DEFAULT '',active TINYINT DEFAULT 1,FOREIGN KEY(cat_id) REFERENCES categories(id) ON DELETE CASCADE) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rtables(num INT PRIMARY KEY) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,token CHAR(16) NOT NULL,table_num INT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'received',note VARCHAR(500) DEFAULT '',reject_reason VARCHAR(255) DEFAULT NULL,total DECIMAL(10,3) NOT NULL,pay_method VARCHAR(20) DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME DEFAULT NULL,INDEX(status),INDEX(created_at)) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,name VARCHAR(120) NOT NULL,price DECIMAL(10,3) NOT NULL,qty INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,pass VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,active TINYINT DEFAULT 1) CHARSET=utf8mb4;
